{
  "name": "cellular_log_analysis_knowledge",
  "language": "zh-CN",
  "version": "1.0",
  "source_file": "knowledge",
  "log_file": "cellular_log_for_AI.log",
  "sections": [
    {
      "index": 1,
      "file": "module_name.log",
      "purpose": "模组名称信息，用来判断模组是否正确初始化、USB驱动或硬件是否断开。",
      "notes": "若初始化未加载5G模组或USB/硬件断开，可能看不到该部分信息。"
    },
    {
      "index": 2,
      "file": "sim_status.log",
      "purpose": "SIM卡状态信息，用于识别SIM卡是否被识别。",
      "notes": "若结论指向SIM卡服务商问题，需要提供该部分信息给客户核查业务。"
    },
    {
      "index": 3,
      "file": "airplane_status.log",
      "purpose": "飞行模式状态，用于排查是否因飞行模式导致业务中断。"
    },
    {
      "index": 4,
      "file": "network_registration_status.log",
      "purpose": "蜂窝网络注册状态，是数据业务的前提。",
      "notes": "包含APN设置、EMM/ESM拒绝码等注册失败原因。"
    },
    {
      "index": 5,
      "file": "ps_status.log",
      "purpose": "PS域状态信息，数据业务的必要前提。",
      "notes": "设备只关心PS域；仅注册CS域会导致数据业务失败。"
    },
    {
      "index": 6,
      "file": "quectel_cm.log",
      "purpose": "QConnectManager_Linux拨号信息。",
      "notes": "在网络注册与PS域正常后用于判断拨号是否成功。"
    },
    {
      "index": 7,
      "file": "ifconfig.log",
      "purpose": "网络接口信息，用于判断是否获得IP及是否为IPv4。",
      "notes": "设备仅支持IPv4数据传输。"
    },
    {
      "index": 8,
      "file": "public_network_status.log",
      "purpose": "公网连通性检测（ping 8.8.8.8 / bing.com）。",
      "notes": "用于判断DNS/公网是否可达，若可达但设备离线，需检查其他配置（如ACMP）。"
    },
    {
      "index": 9,
      "file": "acmp_status.log",
      "purpose": "运维云界面最终在线状态。",
      "notes": "若此处PASS，其他8部分结果可忽略。"
    }
  ],
  "section_format": {
    "start_marker": "SOURCE_FILE: ",
    "end_marker": "END_OF_FILE: ",
    "log_info_tag": "[LOG_INFO]:",
    "conclusion_tag": "[CONCLUSION]:",
    "log_info_optional": true,
    "conclusion_required": true,
    "notes": "每部分日志包含LOG_INFO与CONCLUSION，LOG_INFO可能缺失但CONCLUSION不会缺失。"
  },
  "analysis": {
    "conclusion_order": [
      "module_name.log",
      "sim_status.log",
      "airplane_status.log",
      "network_registration_status.log",
      "ps_status.log",
      "quectel_cm.log",
      "ifconfig.log",
      "public_network_status.log",
      "acmp_status.log"
    ],
    "steps": [
      "读取日志内容，提取九部分日志中[CONCLUSION]所在行的结果（PASS/FAIL）。",
      "按照规则从高优先级到低优先级匹配，输出对应结论。"
    ],
    "rule_match_policy": "first_match_wins",
    "rules": [
      {
        "id": "rule_1_acmp_pass",
        "priority": 1,
        "conditions": {
          "conclusions": {
            "acmp_status.log": "PASS"
          }
        },
        "ignore_other_sections": true,
        "output": {
          "问题原因": "充电桩与运维网络的连接状态正常。",
          "建议措施": [
            "充电桩状态正常则不需要做任何处理。",
            "若你认为充电桩状态异常则检查ACMP地址是否符合预期，或者检查配置相同ACMP信息的其他充电桩状态是否正常，以判断是否ACMP服务器本身问题。"
          }
        }
      },
      {
        "id": "rule_2_acmp_fail_public_pass",
        "priority": 2,
        "conditions": {
          "conclusions": {
            "acmp_status.log": "FAIL",
            "public_network_status.log": "PASS"
          }
        },
        "ignore_other_sections": true,
        "output": {
          "问题原因": "充电桩可以访问公网，无法连接运维网络。",
          "建议措施": [
            "检查ACMP地址是否符合预期，若不符合预期请修正。",
            "若ACMP地址符合预期则使充电桩连接手机热点，进行问题反馈并执行云端深度分析。"
          ]
        }
      },
      {
        "id": "rule_3_ps_pass_cm_fail_public_fail_acmp_fail",
        "priority": 3,
        "conditions": {
          "conclusions": {
            "acmp_status.log": "FAIL",
            "public_network_status.log": "FAIL",
            "quectel_cm.log": "FAIL",
            "ps_status.log": "PASS"
          }
        },
        "ignore_other_sections": true,
        "output": {
          "问题原因": "PS注册成功，但数据拨号失败。",
          "建议措施": [
            "建议联系SIM卡提供商，确认APN 参数是否正确，咨询SIM卡业务是否正常。",
            "2.1、重启设备，看问题是否解决，2.2、重启之后问题无法解决联系技术支持人员使充电桩升级到最新版本。",
            "将该SIM卡插入手机，并在手机设置页面配置同样的APN信息，测试手机能否正常使用数据上网，若手机无法上网则问题锁定在SIM卡异常，需要跟SIM卡商反馈问题或者更换其他SIM卡。若手机插入该SIM卡可以正常上网则使充电桩连接手机热点，进行问题反馈并执行云端深度分析。"
          ]
        }
      },
      {
        "id": "rule_4_module_pass_airplane_fail_network_fail_ps_fail_cm_fail_public_fail_acmp_fail",
        "priority": 4,
        "conditions": {
          "conclusions": {
            "module_name.log": "PASS",
            "airplane_status.log": "FAIL",
            "network_registration_status.log": "FAIL",
            "ps_status.log": "FAIL",
            "quectel_cm.log": "FAIL",
            "public_network_status.log": "FAIL",
            "acmp_status.log": "FAIL"
          }
        },
        "ignore_other_sections": true,
        "output": {
          "问题原因": "移动数据开关被关闭。",
          "建议措施": [
            "打开SIM卡对应的数据开关。",
            "2.1、重启设备，看问题是否解决，2.2、重启之后问题无法解决联系技术支持人员使充电桩升级到最新版本。",
            "若以上操作均无法解决问题，则使充电桩连接手机热点，进行问题反馈并执行云端深度分析。"
          ]
        }
      },
      {
        "id": "rule_5_sim_pass_airplane_pass_network_fail_ps_fail_cm_fail_public_fail_acmp_fail",
        "priority": 5,
        "conditions": {
          "conclusions": {
            "sim_status.log": "PASS",
            "airplane_status.log": "PASS",
            "network_registration_status.log": "FAIL",
            "ps_status.log": "FAIL",
            "quectel_cm.log": "FAIL",
            "public_network_status.log": "FAIL",
            "acmp_status.log": "FAIL"
          }
        },
        "ignore_other_sections": true,
        "subrules": [
          {
            "id": "rule_5a_emm_cause_15",
            "conditions": {
              "log_contains": {
                "network_registration_status.log": "+QNETRC: \"emm_cause\",15"
              }
            },
            "output": {
              "问题原因": "充电桩因被网络拒绝导致无法注册4G/5G网络。",
              "建议措施": [
                "联系SIM提供商，咨询SIM卡业务是否正常，是否欠费。",
                "将SIM卡插入手机，若手机也无法正常上网，则联系SIM卡商寻求解决方案或者更换可在手机中正常使用的SIM卡到充电桩内。",
                "若以上操作均无法解决问题，则使充电桩连接手机热点，进行问题反馈并执行云端深度分析。"
              ]
            }
          },
          {
            "id": "rule_5b_emm_cause_0",
            "conditions": {
              "log_contains": {
                "network_registration_status.log": "+QNETRC: \"emm_cause\",0"
              }
            },
            "output": {
              "问题原因": "充电桩所在地无4G/5G网络信号。",
              "建议措施": [
                "检查充电桩天线连接是否有异常。",
                "将SIM卡插入手机，若手机也无信号格，则更换可在手机中正常使用的SIM卡到充电桩内。",
                "将SIM卡插入手机，若手机信号格正常，则联系技术支持人员排查充电桩是否支持手机所注册的网络频段，若充电桩不支持该频段，则更换支持其他运营商的SIM卡。",
                "若以上操作均无法解决问题，则使充电桩连接手机热点，进行问题反馈并执行云端深度分析。"
              ]
            }
          }
        ]
      },
      {
        "id": "rule_6_sim_fail_airplane_pass_network_fail_ps_fail_cm_fail_public_fail_acmp_fail",
        "priority": 6,
        "conditions": {
          "conclusions": {
            "sim_status.log": "FAIL",
            "airplane_status.log": "PASS",
            "network_registration_status.log": "FAIL",
            "ps_status.log": "FAIL",
            "quectel_cm.log": "FAIL",
            "public_network_status.log": "FAIL",
            "acmp_status.log": "FAIL"
          }
        },
        "ignore_other_sections": true,
        "output": {
          "问题原因": "充电桩SIM卡状态异常。",
          "建议措施": [
            "可能SIM卡未安装或者SIM卡与SIM卡槽的接触异常，检查SIM卡槽里的SIM卡安装是否正常。",
            "将SIM卡插入手机，验证SIM卡本身是否有问题。",
            "SIM卡插入手机之后工作正常，且排除SIM卡槽问题之后，若充电桩依然存在异常，请联系技术支持人员使充电桩升级到最新版本。",
            "若以上操作均无法解决问题，则使充电桩连接手机热点，进行问题反馈并执行云端深度分析。"
          ]
        }
      },
      {
        "id": "rule_7_cm_pass_ifconfig_fail_public_fail_acmp_fail",
        "priority": 7,
        "conditions": {
          "conclusions": {
            "quectel_cm.log": "PASS",
            "ifconfig.log": "FAIL",
            "public_network_status.log": "FAIL",
            "acmp_status.log": "FAIL"
          }
        },
        "ignore_other_sections": true,
        "output": {
          "问题原因": "数据拨号成功但无有效IP问题。",
          "建议措施": [
            "建议联系SIM卡提供商，确认APN 参数是否正确，咨询SIM卡业务是否正常。",
            "2.1、重启设备，看问题是否解决，2.2、重启之后问题无法解决联系技术支持人员使充电桩升级到最新版本。",
            "将该SIM卡插入手机，并在手机设置页面配置同样的APN信息，测试手机能否正常使用数据上网，若手机无法上网则问题锁定在SIM卡异常，需要跟SIM卡商反馈问题或者更换其他SIM卡。若手机插入该SIM卡可以正常上网则使充电桩连接手机热点，进行问题反馈并执行云端深度分析。"
          ]
        }
      }
    ],
    "result_output_template": {
      "fields": [
        "问题原因",
        "建议措施",
        "解决措施"
      ],
      "notes": "最终输出遵循该字段顺序，其中“解决措施”可视为“建议措施”的延展说明。"
    }
  }
}

